// NSI Avatar widget. Provides a guided onboarding experience and bridges
// between the Next Steps Institute profile API and the front‑end embedded
// environment (e.g. Kajabi). See README for usage instructions.

/* eslint-disable no-use-before-define */
(function() {
  function $(q) {
    return document.querySelector(q);
  }
  var NSIAvatar = {
    /**
     * Initialise the avatar widget. Accepts a configuration object with:
     *   mount: selector or DOM element where the widget should render
     *   brand: { primary, accent, logo, name }
     *   apiBase: base URL for API endpoints (e.g. https://api.domain.com)
     *   toolsDomain: base URL for launching tools (e.g. https://tools.domain.com)
     *   memberEmail: optional email to prefill
     */
    init: function(cfg) {
      var mount = typeof cfg.mount === 'string' ? $(cfg.mount) : cfg.mount;
      if (!mount) return;
      var state = { email: cfg.memberEmail || null, api: cfg.apiBase };
      // Build the container HTML once. Body will be updated dynamically.
      var html = '';
      html += '<div id="nsi-panel" style="position:fixed;right:24px;bottom:24px;width:420px;max-width:92vw;border-radius:16px;box-shadow:0 10px 30px rgba(0,0,0,.15);overflow:hidden;background:#fff;font-family:Inter,system-ui">';
      html += '<div style="display:flex;align-items:center;gap:8px;padding:12px 16px;background:' + cfg.brand.primary + ';color:#fff">';
      html += '<img src="' + cfg.brand.logo + '" alt="logo" style="height:20px">';
      html += '<strong style="font-weight:600;margin-left:6px">' + (cfg.brand.name || 'Guide') + '</strong>';
      html += '</div>';
      html += '<div id="nsi-body" style="padding:16px;line-height:1.4"></div>';
      html += '</div>';
      mount.innerHTML = html;
      var body = mount.querySelector('#nsi-body');
      function view(htmlContent) {
        body.innerHTML = htmlContent;
      }
      function button(text, id) {
        return '<button data-id="' + id + '" style="margin-top:12px;padding:10px 12px;border:0;border-radius:10px;background:' + cfg.brand.accent + ';color:#000;font-weight:600;cursor:pointer">' + text + '</button>';
      }
      function on(id, cb) {
        body.addEventListener('click', function(e) {
          var t = e.target;
          if (t.dataset && t.dataset.id === id) {
            cb(e);
          }
        });
      }
      function post(url, payload) {
        return fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        }).then(function(r) { return r.json(); });
      }
      function patch(url, payload) {
        return fetch(url, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        }).then(function(r) { return r.json(); });
      }
      function openTool(email) {
        if (!cfg.toolsDomain) return;
        var u = cfg.toolsDomain + '/navigator?email=' + encodeURIComponent(email);
        window.open(u, '_blank');
      }
      function start() {
        if (!state.email) {
          view('<p>Hi—enter your email to get started.</p>' +
               '<input id="nsi-email" type="email" placeholder="you@example.com" style="width:100%;padding:10px;border:1px solid #ddd;border-radius:8px"><br>' +
               button('Send link', 'send'));
          on('send', function() {
            var email = body.querySelector('#nsi-email').value.trim();
            if (!email) return;
            state.email = email;
            post(state.api + '/api/auth/magic-link', { email: email }).then(function() {
              view('<p>Check your email for a sign-in link. You can continue now.</p>' +
                   button('Continue', 'cont'));
              on('cont', function() {
                startProfile();
              });
            });
          });
          return;
        }
        startProfile();
      }
      function startProfile() {
        view('<p>Tell me a win you’re proud of.</p>' +
             '<textarea id="nsi-ach" rows="4" style="width:100%;padding:10px;border:1px solid #ddd;border-radius:8px"></textarea>' +
             button('Save', 'save-ach'));
        on('save-ach', function() {
          var text = body.querySelector('#nsi-ach').value.trim();
          var proceed = function() {
            view('<p>Pick values that matter to you.</p>' +
                 '<div id="vals">' +
                 '<label><input type="checkbox" value="growth"> Growth</label><br>' +
                 '<label><input type="checkbox" value="autonomy"> Autonomy</label><br>' +
                 '<label><input type="checkbox" value="impact"> Impact</label><br>' +
                 '<label><input type="checkbox" value="flexibility"> Flexibility</label>' +
                 '</div>' +
                 button('Continue', 'save-vals'));
            on('save-vals', function() {
              var checked = body.querySelectorAll('#vals input:checked');
              var vals = [];
              checked.forEach(function(i) { vals.push(i.value); });
              patch(state.api + '/api/profile', { email: state.email, values: vals }).then(function() {
                view('<p>All set! You can now open the Navigator.</p>' +
                     button('Open Navigator', 'open-nav'));
                on('open-nav', function() {
                  openTool(state.email);
                });
              });
            });
          };
          if (text) {
            post(state.api + '/api/achievements', { email: state.email, raw_text: text, source_tool: 'Avatar' }).then(function() { proceed(); });
          } else {
            proceed();
          }
        });
      }
      // Listen for completion messages from tools and record events.
      window.addEventListener('message', function(e) {
        var d = e.data;
        if (d && d.type === 'nsi:tool:complete' && d.tool && state.email) {
          post(state.api + '/api/events', {
            email: state.email,
            tool: d.tool,
            action: 'complete',
            payload_json: d.payload || {}
          }).then(function() {
            view('<p>' + d.tool + ' complete. Want to practice another tool?</p>');
          });
        }
      });
      start();
    }
  };
  // Expose globally
  window.NSIAvatar = NSIAvatar;
})();